-- Données fictives pour la vidéo explicative — organisation HBG Labs (hbtech)
-- Rejouable : tout est identifié par des UUID fixes préfixés a11ce000-.
-- Pour tout retirer : exécuter seulement le bloc « NETTOYAGE ».
begin;

-- ---------------------------------------------------------------- NETTOYAGE
delete from quote_items where quote_id in (select id from quotes where id::text like 'a11ce000-0000-4000-8000-0000000004%');
delete from quotes where id::text like 'a11ce000-0000-4000-8000-0000000004%';
delete from mission_assignments where mission_id::text like 'a11ce000-0000-4000-8000-0000000003%';
delete from missions where id::text like 'a11ce000-0000-4000-8000-0000000003%';
delete from sites where id::text like 'a11ce000-0000-4000-8000-0000000002%';
delete from customer_contacts where id::text like 'a11ce000-0000-4000-8000-0000000005%';
delete from customers where id::text like 'a11ce000-0000-4000-8000-0000000001%';

-- ---------------------------------------------------------------- CLIENTS

-- ---------------------------------------------------------------- CONTACTS

-- ---------------------------------------------------------------- SITES

-- ---------------------------------------------------------------- MISSIONS
-- Membres : 62c91864… = Harry BERGOZ (owner), 4cb3d417… = John Smith (admin)
-- Types : ec6c3fca = Installation, a324218c = Entretien, 21c37e4d = Dépannage, 8b9ecec1 = Visite technique

select m.id, m.assigned_user_id, 'cf7e7290-deec-4d4b-b526-c105451e6f97', m.created_at,
       case when m.status in ('accepted','in_progress','completed','submitted','closed') then m.created_at + interval '1 hour' end
from missions m
where m.id::text like 'a11ce000-0000-4000-8000-0000000003%' and m.assigned_user_id is not null;

-- ---------------------------------------------------------------- DEVIS


commit;

-- Contact principal recopié sur la mission (le trigger de snapshot ne copie que le nom).
update missions m set customer_contact = c.first_name||' '||c.last_name, customer_phone = c.phone, customer_email = c.email
from customer_contacts c
where c.customer_id = m.customer_id and c.is_primary and m.id::text like 'a11ce000-0000-4000-8000-0000000003%';
